#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DTypeKind {
    Bool,
    SignedInteger,
    UnsignedInteger,
    Integral,
    RealFloating,
    ComplexFloating,
    Numeric,
}

pub fn numpy_isdtype(dtype: NumpyDType, kind: DTypeKind) -> bool {
    use DTypeKind::*;
    use NumpyDType::*;

    match kind {
        Bool => matches!(dtype, Bool),

        SignedInteger => matches!(dtype, Int8 | Int16 | Int32 | Int64),

        UnsignedInteger => matches!(dtype, UInt8 | UInt16 | UInt32 | UInt64),

        Integral => matches!(dtype, Int8 | Int16 | Int32 | Int64 | UInt8 | UInt16 | UInt32 | UInt64),

        RealFloating => matches!(dtype, Float16 | Float32 | Float64),

        ComplexFloating => matches!(dtype, Complex64 | Complex128),

        Numeric => matches!(
            dtype,
            Bool
                | Int8
                | Int16
                | Int32
                | Int64
                | UInt8
                | UInt16
                | UInt32
                | UInt64
                | Float16
                | Float32
                | Float64
                | Complex64
                | Complex128
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_bool_kind() {
        assert!(numpy_isdtype(NumpyDType::Bool, DTypeKind::Bool));
        assert!(!numpy_isdtype(NumpyDType::Int8, DTypeKind::Bool));
    }

    #[test]
    fn test_integer_kinds() {
        assert!(numpy_isdtype(NumpyDType::Int32, DTypeKind::SignedInteger));
        assert!(!numpy_isdtype(NumpyDType::UInt32, DTypeKind::SignedInteger));

        assert!(numpy_isdtype(NumpyDType::UInt32, DTypeKind::UnsignedInteger));
        assert!(!numpy_isdtype(NumpyDType::Int32, DTypeKind::UnsignedInteger));

        assert!(numpy_isdtype(NumpyDType::Int16, DTypeKind::Integral));
        assert!(numpy_isdtype(NumpyDType::UInt16, DTypeKind::Integral));
        assert!(!numpy_isdtype(NumpyDType::Float32, DTypeKind::Integral));
    }

    #[test]
    fn test_floating_kinds() {
        assert!(numpy_isdtype(NumpyDType::Float16, DTypeKind::RealFloating));
        assert!(numpy_isdtype(NumpyDType::Float64, DTypeKind::RealFloating));
        assert!(!numpy_isdtype(NumpyDType::Complex64, DTypeKind::RealFloating));

        assert!(numpy_isdtype(NumpyDType::Complex64, DTypeKind::ComplexFloating));
        assert!(!numpy_isdtype(NumpyDType::Float32, DTypeKind::ComplexFloating));
    }

    #[test]
    fn test_numeric_kind() {
        for dt in [
            NumpyDType::Bool,
            NumpyDType::Int8,
            NumpyDType::Int16,
            NumpyDType::Int32,
            NumpyDType::Int64,
            NumpyDType::UInt8,
            NumpyDType::UInt16,
            NumpyDType::UInt32,
            NumpyDType::UInt64,
            NumpyDType::Float16,
            NumpyDType::Float32,
            NumpyDType::Float64,
            NumpyDType::Complex64,
            NumpyDType::Complex128,
        ] {
            assert!(numpy_isdtype(dt, DTypeKind::Numeric), "expected {:?} to be numeric", dt);
        }
    }
}